{"path": "D:\tetris\style.css", "content": ":root {
  --bg: #0f1220;
  --bg-2: #171a2e;
  --panel: #1e2238;
  --panel-2: #262b45;
  --line: #333a5c;
  --text: #e8ecff;
  --muted: #9aa3c7;
  --accent: #5b8cff;
  --accent-2: #7c5cff;
  --danger: #ff5c7a;
  --shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  color: var(--text);
  background:
    radial-gradient(1200px 600px at 15% -10%, #232a52 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 10%, #3a2350 0%, transparent 55%),
    var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.game-wrap {
  width: 100%;
  max-width: 720px;
}

.title {
  text-align: center;
  margin-bottom: 18px;
}

.title h1 {
  margin: 0;
  font-size: 30px;
  letter-spacing: 4px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  letter-spacing: 1px;
}

.stage {
  display: flex;
  gap: 20px;
  align-items: flex-start;
  justify-content: center;
}

/* ---------- 游戏区 ---------- */
.board-panel {
  position: relative;
  border-radius: 14px;
  padding: 10px;
  background: linear-gradient(180deg, var(--panel), var(--bg-2));
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
}

#board {
  display: block;
  border-radius: 8px;
  background: #0b0e1a;
}

/* ---------- 侧栏 ---------- */
.side-panel {
  width: 190px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.card {
  background: linear-gradient(180deg, var(--panel), var(--panel-2));
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 12px 14px;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
}

.card h3 {
  margin: 0 0 8px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 2px;
  color: var(--muted);
  text-transform: uppercase;
}

.card .value {
  font-size: 26px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

#next {
  display: block;
  margin: 0 auto;
  background: #0b0e1a;
  border-radius: 8px;
}

.controls ul {
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12.5px;
  color: var(--muted);
  line-height: 1.9;
}

kbd {
  display: inline-block;
  min-width: 20px;
  padding: 1px 6px;
  margin-right: 2px;
  font-family: inherit;
  font-size: 11px;
  text-align: center;
  color: var(--text);
  background: #0b0e1a;
  border: 1px solid var(--line);
  border-bottom-width: 2px;
  border-radius: 5px;
}

/* ---------- 按钮 ---------- */
.btn {
  width: 100%;
  padding: 11px 14px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--text);
  background: linear-gradient(180deg, var(--panel-2), var(--panel));
  border: 1px solid var(--line);
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.08s ease, filter 0.15s ease, box-shadow 0.15s ease;
}

.btn:hover { filter: brightness(1.15); }
.btn:active { transform: translateY(1px); }

.btn.primary {
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  border-color: transparent;
  box-shadow: 0 10px 24px rgba(91, 140, 255, 0.35);
}

/* ---------- 遮罩层 ---------- */
.overlay {
  position: absolute;
  inset: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(8, 10, 20, 0.78);
  backdrop-filter: blur(3px);
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-card {
  text-align: center;
  padding: 22px 26px;
}

.overlay-card h2 {
  margin: 0 0 8px;
  font-size: 24px;
  letter-spacing: 2px;
}

.overlay-card p {
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 13px;
}

.overlay-card .btn { width: auto; padding: 10px 22px; }

/* ---------- 响应式 ---------- */
@media (max-width: 620px) {
  .stage { flex-direction: column; align-items: center; }
  .side-panel {
    width: 100%;
    max-width: 320px;
    flex-direction: row;
    flex-wrap: wrap;
  }
  .side-panel .card { flex: 1 1 40%; }
  .side-panel .controls { flex: 1 1 100%; }
  #restart { flex: 1 1 100%; }
}
